using FinanSmart.Api.Common.Exceptions;using FinanSmart.Api.Modules.Investments.Simulations.DTOs;using FinanSmart.Api.Modules.Investments.Simulations.Interfaces;using Microsoft.AspNetCore.Mvc;namespace FinanSmart.Api.Modules.Investments.Simulations.Controllers;[ApiController][Route("api/investment-simulations")]public class InvestmentSimulationsController(IInvestmentSimulationService service):ControllerBase{[HttpPost("simulate")]public async Task<ActionResult<InvestmentSimulationResponseDto>> Simulate(InvestmentSimulationRequestDto r){try{return Ok(await service.SimulateAsync(r));}catch(InvestmentProductNotFoundException e){return NotFound(new{message=e.Message});}catch(ArgumentException e){return BadRequest(new{message=e.Message});}}}
